const ParseError = error{ MissingValue, InvalidNumber };

fn parseNumber(text: []const u8) ParseError!i32 {
    if (text.len == 0) return error.MissingValue;
    return std.fmt.parseInt(i32, text, 10) catch error.InvalidNumber;
}

fn double(text: []const u8) !u32 {
    const value = try std.fmt.parseInt(u32, text, 10);
    return std.math.mul(u32, value, 2);
}

fn parseOrDefault(text: []const u8, fallback: u32) u32 {
    return std.fmt.parseInt(u32, text, 10) catch fallback;
}

