var resource_open: bool = false;

fn acquire(should_fail: bool) !void {
    resource_open = true;
    errdefer resource_open = false;
    if (should_fail) return error.Unavailable;
}

fn observeErrdefer() !void {
    try acquire(false);
    std.debug.assert(resource_open);
    resource_open = false;
    acquire(true) catch {};
    std.debug.assert(resource_open == false);
}

