const Inventory = struct {
    allocator: std.mem.Allocator,
    names: std.ArrayList([]const u8),

    fn init(allocator: std.mem.Allocator) Inventory {
        return .{ .allocator = allocator, .names = .empty };
    }

    fn deinit(self: *Inventory) void {
        self.names.deinit(self.allocator);
    }

    fn add(self: *Inventory, name: []const u8) !void {
        for (self.names.items) |existing| {
            if (std.mem.eql(u8, existing, name)) return error.DuplicateItem;
        }
        try self.names.append(self.allocator, name);
    }

    fn count(self: Inventory) usize {
        return self.names.items.len;
    }
};

