    defer inventory.deinit();
    try inventory.add("keyboard");
    try std.testing.expect(std.mem.eql(u8, inventory.names.items[0], "keyboard"));
    try std.testing.expectEqual(@as(usize, 1), inventory.count());
    try std.testing.expectError(error.DuplicateItem, inventory.add("keyboard"));
}

fn linearSearch(values: []const i32, target: i32) ?usize {
    for (values, 0..) |value, index| {
        if (value == target) return index;
    }
    return null;
}

fn binarySearch(values: []const i32, target: i32) ?usize {
    var low: usize = 0;
    var high: usize = values.len;
    while (low < high) {
        const middle = low + (high - low) / 2;
        if (values[middle] == target) return middle;
        if (values[middle] < target) {
            low = middle + 1;
        } else {
            high = middle;
        }
    }
    return null;
}

fn bubbleSort(values: []i32) void {
    if (values.len < 2) return;
    var end = values.len;
    while (end > 1) {
        end -= 1;
        var swapped = false;
        for (0..end) |index| {
            if (values[index] > values[index + 1]) {
                std.mem.swap(i32, &values[index], &values[index + 1]);
                swapped = true;
            }
        }
        if (!swapped) return;
    }
}

fn selectionSort(values: []i32) void {
    if (values.len < 2) return;
    var start: usize = 0;
    while (start + 1 < values.len) : (start += 1) {
        var minimum = start;
        for (start + 1..values.len) |index| {
            if (values[index] < values[minimum]) minimum = index;
        }
        if (minimum != start) {
            std.mem.swap(i32, &values[start], &values[minimum]);
        }
    }
}

fn insertionSort(values: []i32) void {
    if (values.len < 2) return;
    var index: usize = 1;
    while (index < values.len) : (index += 1) {
        const current = values[index];
        var position = index;
        while (position > 0 and values[position - 1] > current) : (position -= 1) {
            values[position] = values[position - 1];
        }
        values[position] = current;
    }
}

fn mergeSort(allocator: std.mem.Allocator, values: []const i32) ![]i32 {
    if (values.len <= 1) return try allocator.dupe(i32, values);
    const middle = values.len / 2;
    const left = try mergeSort(allocator, values[0..middle]);
    defer allocator.free(left);
    const right = try mergeSort(allocator, values[middle..]);
    defer allocator.free(right);
    const result = try allocator.alloc(i32, values.len);
    errdefer allocator.free(result);
    var left_index: usize = 0;
    var right_index: usize = 0;
    var output_index: usize = 0;
    while (left_index < left.len and right_index < right.len) {
        if (left[left_index] <= right[right_index]) {
            result[output_index] = left[left_index];
            left_index += 1;
        } else {
            result[output_index] = right[right_index];
            right_index += 1;
        }
        output_index += 1;
    }
    while (left_index < left.len) : (left_index += 1) {
        result[output_index] = left[left_index];
        output_index += 1;
    }
    while (right_index < right.len) : (right_index += 1) {
        result[output_index] = right[right_index];
        output_index += 1;
    }
    return result;
}

fn quickSort(values: []i32) void {
    if (values.len < 2) return;
    const pivot = values[values.len - 1];
    var boundary: usize = 0;
    for (0..values.len - 1) |index| {
        if (values[index] < pivot) {
            std.mem.swap(i32, &values[boundary], &values[index]);
            boundary += 1;
        }
    }
    std.mem.swap(i32, &values[boundary], &values[values.len - 1]);
    quickSort(values[0..boundary]);
    quickSort(values[boundary + 1 ..]);
}

fn siftDown(values: []i32, start: usize, size: usize) void {
    var root = start;
    while (true) {
        const left = root * 2 + 1;
        if (left >= size) return;
        var largest = left;
        const right = left + 1;
        if (right < size and values[right] > values[left]) largest = right;
        if (values[root] >= values[largest]) return;
        std.mem.swap(i32, &values[root], &values[largest]);
        root = largest;
    }
}

fn heapSort(values: []i32) void {
    if (values.len < 2) return;
    var parent = values.len / 2;
    while (parent > 0) {
        parent -= 1;
        siftDown(values, parent, values.len);
    }
    var end = values.len;
    while (end > 1) {
        end -= 1;
        std.mem.swap(i32, &values[0], &values[end]);
        siftDown(values, 0, end);
    }
}

const Edge = struct {
    to: usize,
    weight: u64,
};

const Graph = struct {
    adjacency: []const []const Edge,
};

fn validateGraph(graph: Graph) !void {
    for (graph.adjacency) |edges| {
        for (edges) |edge| {
            if (edge.to >= graph.adjacency.len) return error.InvalidEdge;
        }
    }
}

const sample_edges = [_]Edge{
    .{ .to = 1, .weight = 2 },
    .{ .to = 2, .weight = 1 },
};
const sample_adjacency = [_][]const Edge{
    sample_edges[0..1],
    sample_edges[1..2],
    &.{},
};
const sample_graph = Graph{ .adjacency = &sample_adjacency };

comptime {
    validateGraph(sample_graph) catch unreachable;
}

fn breadthFirst(allocator: std.mem.Allocator, graph: Graph, start: usize) ![]usize {
    try validateGraph(graph);
    if (start >= graph.adjacency.len) return error.InvalidStart;
    const visited = try allocator.alloc(bool, graph.adjacency.len);
    defer allocator.free(visited);
    @memset(visited, false);
    var queue = std.ArrayList(usize).empty;
    defer queue.deinit(allocator);
    var order = std.ArrayList(usize).empty;
    errdefer order.deinit(allocator);
    visited[start] = true;
    try queue.append(allocator, start);
    var head: usize = 0;
    while (head < queue.items.len) : (head += 1) {
        const current = queue.items[head];
        try order.append(allocator, current);
        for (graph.adjacency[current]) |edge| {
            if (!visited[edge.to]) {
                visited[edge.to] = true;
                try queue.append(allocator, edge.to);
            }
        }
    }
    return order.toOwnedSlice(allocator);
}

fn depthFirstVisit(
    allocator: std.mem.Allocator,
    graph: Graph,
    node: usize,
    visited: []bool,
    order: *std.ArrayList(usize),
) !void {
    if (visited[node]) return;
    visited[node] = true;
    try order.append(allocator, node);
    for (graph.adjacency[node]) |edge| {
        try depthFirstVisit(allocator, graph, edge.to, visited, order);
    }
}

fn depthFirst(allocator: std.mem.Allocator, graph: Graph, start: usize) ![]usize {
    try validateGraph(graph);
    if (start >= graph.adjacency.len) return error.InvalidStart;
    const visited = try allocator.alloc(bool, graph.adjacency.len);
    defer allocator.free(visited);
    @memset(visited, false);
    var order = std.ArrayList(usize).empty;
    errdefer order.deinit(allocator);
    try depthFirstVisit(allocator, graph, start, visited, &order);
    return order.toOwnedSlice(allocator);
}

fn dijkstra(
    graph: Graph,
    start: usize,
    distances: []?u64,
    visited: []bool,
) !void {
    try validateGraph(graph);
    if (start >= graph.adjacency.len or
        distances.len != graph.adjacency.len or
        visited.len != graph.adjacency.len)
    {
        return error.InvalidInput;
    }
    const max_distance = std.math.maxInt(u64);
    @memset(distances, null);
    @memset(visited, false);
    distances[start] = 0;
    var remaining = graph.adjacency.len;
    while (remaining > 0) {
        var current: usize = 0;
        var found = false;
        var best_distance: u64 = max_distance;
        for (distances, 0..) |maybe_distance, vertex| {
            if (visited[vertex]) continue;
            if (maybe_distance) |distance| {
                if (!found or distance < best_distance) {
                    current = vertex;
                    best_distance = distance;
                    found = true;
                }
            }
        }
        if (!found) return;
        visited[current] = true;
        remaining -= 1;
        const current_distance = distances[current].?;
        for (graph.adjacency[current]) |edge| {
            if (current_distance > max_distance - edge.weight) continue;
            const candidate = current_distance + edge.weight;
            const previous = distances[edge.to];
            if (previous == null or candidate < previous.?) {
                distances[edge.to] = candidate;
            }
        }
    }
}
